import json
from datetime import datetime

def format_restaurant_info(restaurant):
    return {
        "name": restaurant.get("name", "N/A"),
        "rating": restaurant.get("rating", "N/A"),
        "address": restaurant.get("address", "N/A"),
        "price_per_person": restaurant.get("price_per_person", "N/A"),
        "operating_hours": restaurant.get("operating_hours", "N/A")
    }

def find_best_restaurant(restaurants):
    if not restaurants:
        return None
    return max(restaurants, key=lambda x: float(x.get("rating", 0)))

